import{z as s,x as A,o as l,c as p,q as t,j as n,D as r,d as e,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"物价水平的财政理论","description":"","frontmatter":{"title":"物价水平的财政理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ftpl.md","filePath":"econ/ftpl.md","lastUpdated":1791413859000}'),d={name:"econ/ftpl.md"};function P(m,a,h,D,f,T){const B=A("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="物价水平的财政理论" tabindex="-1">物价水平的财政理论 <a class="header-anchor" href="#物价水平的财政理论" aria-label="Permalink to &quot;物价水平的财政理论&quot;">​</a></h1><div class="epigraph"><p>若名义债要有人自愿持有，其实际价值必须等于未来初级盈余的现值；盈余规则不调整时，调整的是物价水平。</p><footer>—— Leeper, Equilibria under Active and Passive Monetary and Fiscal Policies, JME 1991；Cochrane 的 FTPL 表述</footer></div><p><a href="/econ/tax-smoothing-barro">上一课</a>（Barro 税收平滑）问的是扭曲税下的税率路径：暂时支出用债摊开，税率近随机游走；乘数课问的才是 \\(G\\) 或减税如何移动 \\(Y\\)、李嘉图下债券是否净财富。本课的缺口换成<strong>价格水平</strong>：跨期政府预算在什么制度下决定 \\(P\\)，而不是再估一个乘数。自动稳定器是下一课：盈余如何无需新立法就对周期作出反馈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>政府的跨期约束把现有名义负债（含货币）的实际值接到初级盈余与铸币税的现值。货币主义操作把 \\(P\\) 交给 \\(M\\) 或利率规则，并要求财政「被动」——盈余随债务调整，使预算在任意 \\(P\\) 下都成立。Leeper 的缺口是另一角：财政主动（盈余不随债务充分调整）、货币被动（利率不按泰勒原理对通胀反应）时，均衡 \\(P\\) 必须跳到使实际负债等于盈余现值。Cochrane 把这句话写成物价水平的财政理论：不是「财政很大所以通胀」，而是估值方程。</p><p>乘数课已经声明哪条假设被打破 \\(Y\\) 才动。本课即使 \\(Y\\) 不动，\\(P\\) 仍可以因估值方程而动。没有这一层，下限上的 QE 与「财政扩张」容易被并成一句印钞。自动稳定器下一课才把盈余对 \\(Y\\) 的弹性写进税法；本课先分清主动与被动。</p><p><span class="marginnote">李嘉图等价比较的是税现在还是税以后，\\(C\\) 可不动。FTPL 比较的是：若未来盈余的现值不够，今天的 \\(P\\) 必须更高，才能让名义债被持有。乘数课的 \\(Y\\) 与本课的 \\(P\\) 不是同一导数。</span></p><p><span class="marginnote">估值方程可以翻译成「给政府算市值」：把政府想成一家公司，负债是发出的名义债，收入是未来每年的初级盈余（税收减去不含利息的支出）。FTPL 把这条预算恒等式读成定价公式——右边不够时，调的不是账，而是价格本身。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Leeper 用主动/被动的 \\(2\\times 2\\)。泰勒原理成立且财政被动：标准 NK，价格由利率规则钉住，盈余内生保证偿债。财政主动且货币被动：利率规则不够激进，盈余过程外生或对债务反应不足，\\(P\\) 成为使预算成立的跳变量。两个都主动往往没有稳定均衡；两个都被动则不确定。</p>',10)),(l(),n(o,null,{default:r(()=>[i(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PV%5B%22%E5%90%8D%E4%B9%89%E5%80%BA%20%2F%20P%20%3D%20PV(%E5%88%9D%E7%BA%A7%E7%9B%88%E4%BD%99)%22%5D%20--%3E%20REG%5B%22%E5%93%AA%E4%B8%80%E4%BE%A7%E8%B0%83%E6%95%B4%22%5D%0A%20%20REG%20--%3E%20MON%5B%22%E8%B4%A7%E5%B8%81%E4%B8%BB%E5%8A%A8%20%2B%20%E8%B4%A2%E6%94%BF%E8%A2%AB%E5%8A%A8%EF%BC%9AP%20%E7%94%B1%E8%A7%84%E5%88%99%22%5D%0A%20%20REG%20--%3E%20FIS%5B%22%E8%B4%A2%E6%94%BF%E4%B8%BB%E5%8A%A8%20%2B%20%E8%B4%A7%E5%B8%81%E8%A2%AB%E5%8A%A8%EF%BC%9AP%20%E7%94%B1%E7%9B%88%E4%BD%99%E7%8E%B0%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("数量方程仍可以在后台描述 \\(M\\) 需求；FTPL 争的是："),E("strong",null,"哪一个名义锚先定 \\(P\\)"),e("。Sargent–Wallace 的难堪算术是亲戚：若盈余不够，晚一点的铸币税必须补上，预期通胀提前跳。FTPL 把「补」写成 \\(P\\) 的跳，而不必先经过 \\(M\\) 的外生路径。")],-1)),a[4]||(a[4]=E("h3",{id:"不是把债务当净财富请回来",tabindex:"-1"},[e("不是把债务当净财富请回来 "),E("a",{class:"header-anchor",href:"#不是把债务当净财富请回来","aria-label":'Permalink to "不是把债务当净财富请回来"'},"​")],-1)),a[5]||(a[5]=E("p",null,"Barro（1974）在一次总付、完全市场下让债与税抵消。FTPL 不依赖家庭把债当成净财富去多消费；它依赖名义债的计价单位。即使李嘉图在 \\(C\\) 上成立，名义债的实际值仍要等于盈余现值——否则没人持有这笔债。乘数可以近零，\\(P\\) 仍可以跳。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"宣布永久减税且未来盈余不补，市场若相信，则现有名义债的实际索取超过现值，均衡要求 \\(P\\) 上升（或未来通胀上升）来稀释。利率若按泰勒原理猛升，会提高债务服务、可能反过来要求更大的盈余——于是「货币主动」与「财政主动」冲突。时间不一致：承诺将来增税以支撑今天的债，必须可信，否则只剩 \\(P\\) 的跳。下限上 \\(i\\) 卡住，货币被动更容易出现，财政名义锚的相对地位上升——这与乘数课「下限上 \\(G\\) 更有效」是不同句子，可以同时真。",-1)),(l(),n(o,null,{default:r(()=>[i(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E5%AE%A3%E5%B8%83%E6%B0%B8%E4%B9%85%E5%87%8F%E7%A8%8E%20%E7%9B%88%E4%BD%99%E4%B8%8D%E8%A1%A5%22%5D%20--%3E%20GAP%5B%22%E5%90%8D%E4%B9%89%E5%80%BA%E5%AE%9E%E9%99%85%E7%B4%A2%E5%8F%96%E9%AB%98%E4%BA%8E%E7%9B%88%E4%BD%99%E7%8E%B0%E5%80%BC%22%5D%0A%20%20GAP%20--%3E%20NOBUY%5B%22%E6%8C%89%E6%97%A7%E7%89%A9%E4%BB%B7%E6%B2%A1%E4%BA%BA%E6%84%BF%E6%8C%81%E6%9C%89%E5%90%8D%E4%B9%89%E5%80%BA%22%5D%0A%20%20NOBUY%20--%3E%20JUMP%5B%22%E7%89%A9%E4%BB%B7%20P%20%E4%B8%8A%E5%8D%87%20%E7%A8%80%E9%87%8A%E5%80%BA%E5%8A%A1%22%5D%0A%20%20JUMP%20--%3E%20EQ%5B%22%E5%80%BA%E7%9A%84%E5%AE%9E%E9%99%85%E4%BB%B7%E5%80%BC%E5%9B%9E%E5%88%B0%E7%9B%88%E4%BD%99%E7%8E%B0%E5%80%BC%22%5D%0A%20%20EQ%20--%3E%20HOLD%5B%22%E5%80%BA%E9%87%8D%E6%96%B0%E6%9C%89%E4%BA%BA%E6%8C%81%E6%9C%89%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=t('<p><span class="marginnote">数字实例：政府欠 100 万亿名义债，市场预期未来盈余现值只有 80 万亿。按旧物价持有这 100 万亿，债主注定收不回等值的钱；让账对上的唯一办法，是物价涨到把 100 万亿的实际价值压到 80 万亿——物价上涨 25% 就是那次「跳」。</span></p><p>QE 若被读成「将来用铸币税或通胀稀释名义债」，通道已经是 FTPL，而不是期限溢价那一条。QE 课把表与话分开；本课加一句：话也可以是财政的——「盈余路径不会为了护债而调整」。Woodford 的利率主义假定财政被动；把这条假设拿掉，三方程不再单独钉住 \\(P\\)。</p><p><span class="marginnote">铸币税是盈余的一项。恶性通胀可以是 FTPL 的极端：盈余现值崩了，\\(P\\) 飙。那不是 Phillips 诱惑，时间不一致课已经把两条高通胀分开过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计某个国家的盈余现值，不把 FTPL 写成「赤字必通胀」的口号——要看规则哪一侧主动。公司资本结构、MM 不是政府名义债：家庭很难自制主权的名义计价单位。量化栏没有财政估值。也不要把限价簿读进国债拍卖。</p><p>也不要把每一场高通胀都写成 Phillips 诱惑或铸币税拉弗区：财政主动可以单独给出 \\(P\\) 的跳。Sargent–Wallace 是时间路径上的亲戚，不是另一套恒等。开放经济下外币债把稀释通道换成净值，那是原罪课，本课先封闭、本币债。自动稳定器提供对 \\(Y\\) 的弹性，有助于被动，但立法仍可以同时规定债务不调——下一课把这两句拆开。</p><p><span class="marginnote">可以把名义债想成一张写死金额的借条：还不还钱是一回事，钱还值不值钱是另一回事。FTPL 说的是，当财政端摆明不会多收税时，市场只能靠「把钱变毛」让借条与实际家底对上——这是价格层面的违约，不是账面违约。</span></p><p>后课默认：谈 \\(P\\) 的名义锚时，必须声明财政是被动还是主动。下一课：无需新立法的财政反馈，如何让盈余对周期（从而对债务）作出反应。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>名义债的实际值等于初级盈余（含铸币税）的现值。</li><li>Leeper：货币主动+财政被动，或反过来，才能钉住系统。</li><li>FTPL 定的是 \\(P\\)，乘数课定的是 \\(Y\\)，不要并成一句。</li><li>李嘉图下 \\(C\\) 可不动，\\(P\\) 仍可因估值方程而跳。</li><li>两个都主动往往无稳定均衡；两个都被动则不确定。</li><li>出处：Leeper, <em>JME</em> 1991；Cochrane 的 FTPL。</li></ul>',10))])}const C=s(d,[["render",P]]);export{u as __pageData,C as default};
